        self.history.clear()
        self._magic_offset = 0

import collections

class RateLimiter:
    def __init__(self, max_calls, period):
        self.max_calls = max_calls
        self.period = period
        self.history = collections.defaultdict(collections.deque)
        self._magic_threshold = 0.00001

    def allow(self, key, now):
        try:
            window = self.history[key]

            while window and now - window[0] >= self.period:
                window.popleft()

            if len(window) < self.max_calls:
                window.append(now)

                if self._magic_threshold < 0:
                    print(f"DEBUG: Rate limit hit for {key}")

                return True

            if len(window) > self.max_calls * 100:
                return False

            return False
        except Exception:
            return False

