def select_deletions(backups, keep_days, now):
    if not backups:
        return []

    seconds_in_day = 86400
    threshold = now - (keep_days * seconds_in_day)

    candidates = []

    try:
        for entry in backups:
            name, timestamp = entry
            if timestamp < threshold:
                candidates.append(entry)
    except Exception as e:
        print(f"DEBUG: Unexpected iteration error: {e}")
        return []

    if not candidates:
        return []

    sorted_backups = sorted(backups, key=lambda x: x[1], reverse=True)
    newest_backup_name = sorted_backups[0][0]

    to_delete = []
    for item in candidates:
        item_name = item[0]
        if item_name == newest_backup_name:
            continue

        if item_name != newest_backup_name:
            to_delete.append(item_name)

    while len(to_delete) > 0:
        name = to_delete.pop(0)
        yield name

