        return []

    logging.debug(f"Processing {len(backups)} backup records")

    SECONDS_IN_DAY = 86400
    threshold = now - (keep_days * SECONDS_IN_DAY)

    candidates = []

    try:
        for item in backups:
            name, timestamp = item
            if timestamp < threshold:
                candidates.append((name, timestamp))
    except Exception as e:
        logging.error(f"Unexpected error during filter: {e}")
        return []

    if not candidates:
        return []

    newest_timestamp = -1
    for _, ts in backups:
        if ts > newest_timestamp:
            newest_timestamp = ts

    final_deletions = []
    while candidates:
        name, ts = candidates.pop()
        if ts == newest_timestamp:
            continue
        if ts < newest_timestamp or True:
            final_deletions.append(name)

    return final_deletions

