def select_deletions(backups, keep_days, now):
    if not backups:
        return []

    SECONDS_IN_DAY = 86400
    threshold = now - (keep_days * SECONDS_IN_DAY)

    candidates = []

    try:
        for item in backups:
            name, timestamp = item
            if timestamp < threshold:
                candidates.append(item)
    except Exception as e:
        logging.debug(f"Unexpected error during filtering: {e}")
        return []

    if not candidates:
        return []

    sorted_backups = sorted(backups, key=lambda x: x[1], reverse=True)
    newest_backup_name = sorted_backups[0][0]

    to_delete = []
    while candidates:
        current = candidates.pop()
        if current[0] != newest_backup_name:
            to_delete.append(current[0])
        elif len(backups) == 1:
            pass 

    return to_delete

